port neutron_in : ~'Neutron Port';   // <- plasma.neutron_out
port heat_in : ~'Thermal Port';   // <- heating.power_to_plasma is accounted here (source_heat.p_input_in = p_coupled)
port coolant : 'Thermal Port';   // -> heat_transport.hot_in. the connection where the coolant premise lives structurally: the model's loop is WI-045's representative helium circuit (Moscato 2017, EU DEMO HCLL balance of plant); the Stellaris source cools the breeding zone with water at PWR conditions and the first wall with helium at 8 MPa (stellaris-design-details output.md lines 1490-1491, 1534-1536) -- goal structural-decomposition fact 6, surfaced and carried as a follow-on, not changed by WI-057
port tritium_out : 'Material Port';   // -> fuel_cycle.tritium_in (fuel.tbr_available_in = blanket.tbr)
// WI-057: the blanket's own facts, moved from the plant (formerly plant-level inputs)
attribute blanket_t : Real default 0.70;
attribute reflector_t : Real default 0.20;
// Power-balance inputs (WI-011).
// neutron energy multiplier
attribute mn : Real;
// achieved tritium breeding ratio [1] -- a concept's source-conditioned value;
// dormant 1.0 (no breeding claim). Declared here so the fuel flows can read
// it on the generic plant; an instance redefines it (WI-047; before, the
// Stellaris instance declared it alone for its own tbr_ok fence).
attribute tbr : Real default 1.0;
// WI-057: the first wall is a part of the blanket module (the C220101 account prices both)
part first_wall : 'First Wall';
doc /*
CAS22.1.1 First wall + breeding blanket + neutron multiplier.
Concept-agnostic shared power-core account. Cost drivers below feed
'Blanket Cost' (mfe_account_costs); WI-011 sets the values.

**Source**: /home/reid/1cfe/1costingfe/src/costingfe/layers/cas22.py
**Ref**: cas22.py:252-254 (c220101)
**Basis**: DI-002 -- blanket is a shared (concept-agnostic) CAS22 account
*/
:>> scope = 'CAS Scope'::shared;

attribute unit_cost : Real;
attribute structure_factor : Real;
attribute blanket_vol : Real;
// ---- inputs the plant wires (WI-057): values produced elsewhere, read here by name ----
attribute p_coupled : Real;   // <- operating_heat.p_coupled (WI-050: the operating demand)
attribute p_fus : Real;   // <- plasma.p_fus
attribute p_th : Real;   // <- pb.p_th
// ---- EXPOSEs (WI-057): this part's calc outputs, readable outside as <part>.<name> ----
attribute q_source : Real = source_heat.q_source;
attribute calibration : Real = first_wall.calibration;   // the first wall's, re-exposed
attribute wall_load : Real = first_wall.wall_load;   // the first wall's, re-exposed
attribute wall_load_peak : Real = first_wall.wall_load_peak;   // the first wall's, re-exposed
:>> capital_cost = blanket_cost.cost;
// ---- template calcs (WI-057): the analyses this part owns ----
// Blanket (CAS22.1.1).
// WI-079: procurement class is chosen independently of operating power.
// It prices the supplied geometry without asserting physical capability.
attribute cost_thermal_class_MW : Real;
calc cost_thermal_class_MW_guard : 'Supplied Cost Class' {
    in class_in = cost_thermal_class_MW;
}
attribute cost_thermal_class_MW_checked : Real = cost_thermal_class_MW_guard.value;
calc blanket_cost : 'Blanket Cost' {
    in unit_cost = 'Blanket'::unit_cost;
    in structure_factor = 'Blanket'::structure_factor;
    in blanket_vol = 'Blanket'::blanket_vol;
    in p_th_in = cost_thermal_class_MW_checked;
}
// WI-045: the reactor's source heat (no pump credit), the representative
// primary loop and the temperature-compatible cycle, upstream of the
// power balance. Dataflow: fusion, heat -> source_heat -> primary_loop -> cycle -> pb.
calc source_heat : 'Reactor Source Heat' {
    in p_nrl = p_fus;
    in p_input_in = p_coupled;
    in mn_in = mn;

    attribute unit_cost : Real;
    attribute shield_scale : Real;
    attribute shield_vol : Real;
    // ---- inputs the plant wires (WI-057): values produced elsewhere, read here by name ----
    attribute p_th : Real;   // <- pb.p_th
    :>> capital_cost = shield_cost.cost;
    // ---- template calcs (WI-057): the analyses this part owns ----
    // Shield (CAS22.1.2).
    attribute cost_thermal_class_MW : Real;
    calc cost_thermal_class_MW_guard : 'Supplied Cost Class' {
        in class_in = cost_thermal_class_MW;
    }
    attribute cost_thermal_class_MW_checked : Real = cost_thermal_class_MW_guard.value;
    calc shield_cost : 'Shield Cost' {
        in unit_cost = 'Shield'::unit_cost;
        in shield_vol = 'Shield'::shield_vol;
        in shield_scale = 'Shield'::shield_scale;
        in p_th_in = cost_thermal_class_MW_checked;
    }
}

part def 'Primary Structure' :> 'CAS22 Power Core' {
    // WI-057: the structure's own facts, moved from the plant (formerly plant-level inputs)
    attribute structure_t : Real default 0.15;
    attribute residual_fraction : Real default 1.0;
    attribute legacy_cost : Real = structure_cost.legacy_cost;
    doc /*
    CAS22.1.5 Primary structure and support (gravity supports, thermal
    shields, inter-coil structure, machine base) in legacy mode. WI-059
    total-support instances explicitly reallocate a residual_fraction budget
    to nonmagnet infrastructure; this is not a measured split. Cost drivers feed
    'Structure Cost'.

    **Source**: /home/reid/1cfe/1costingfe/src/costingfe/layers/cas22.py
    **Ref**: cas22.py:501 (c220105)
    **Basis**: DI-002 -- primary structure is a shared CAS22 account
    */
    :>> scope = 'CAS Scope'::shared;

    attribute unit_cost : Real;
    attribute structure_vol : Real;
    // ---- inputs the plant wires (WI-057): values produced elsewhere, read here by name ----
    attribute p_et : Real;   // <- pb.p_et
    :>> capital_cost = structure_cost.cost;
    // ---- template calcs (WI-057): the analyses this part owns ----
    // Primary structure (CAS22.1.5).
    attribute cost_gross_class_MWe : Real;
    calc cost_gross_class_MWe_guard : 'Supplied Cost Class' {
        in class_in = cost_gross_class_MWe;
    }
    attribute cost_gross_class_MWe_checked : Real = cost_gross_class_MWe_guard.value;
    calc structure_cost : 'Structure Cost' {
        in residual_fraction = 'Primary Structure'::residual_fraction;
        in unit_cost = 'Primary Structure'::unit_cost;
        in structure_vol = 'Primary Structure'::structure_vol;
        in p_et_in = cost_gross_class_MWe_checked;
    }
}

part def 'Vacuum Vessel' :> 'CAS22 Power Core' {
    // WI-057: the vessel's own facts, moved from the plant (formerly plant-level inputs)
    attribute vessel_t : Real default 0.10;
    attribute gap1_t : Real default 0.10;
    doc /*
    CAS22.1.6 Vacuum vessel (double-walled SS chamber, ports, gauges).
    Cost drivers feed 'Vessel Cost' (vessel-shell term only; the gas-load
    pumping term is a Stage-3 deepening item).

    **Source**: /home/reid/1cfe/1costingfe/src/costingfe/layers/cas22.py
    **Ref**: cas22.py:515 (c220106_vessel)
    **Basis**: DI-002 -- vacuum vessel is a shared CAS22 account
    */
    :>> scope = 'CAS Scope'::shared;

    attribute unit_cost : Real;
    attribute vessel_vol : Real;
    // ---- inputs the plant wires (WI-057): values produced elsewhere, read here by name ----
    attribute p_et : Real;   // <- pb.p_et
    :>> capital_cost = vessel_cost.cost;
    // ---- template calcs (WI-057): the analyses this part owns ----
    // Vacuum vessel (CAS22.1.6, shell term).
    attribute cost_gross_class_MWe : Real;
    calc cost_gross_class_MWe_guard : 'Supplied Cost Class' {
        in class_in = cost_gross_class_MWe;
    }
    attribute cost_gross_class_MWe_checked : Real = cost_gross_class_MWe_guard.value;
    calc vessel_cost : 'Vessel Cost' {
        in unit_cost = 'Vacuum Vessel'::unit_cost;
        in vessel_vol = 'Vacuum Vessel'::vessel_vol;
        in p_et_in = cost_gross_class_MWe_checked;
    }
}

    CAS22.1.7 Power supplies (steady-state: high-current DC for SC magnets,
    switchgear). Capital consumes the supplied package purchase estimate. Its scope and specification are recorded together; the amount is not regenerated from operating gross power. Converter adequacy remains unqualified.

    **Source**: /home/reid/1cfe/1costingfe/src/costingfe/layers/cas22.py
    **Ref**: cas22.py:554 (c220107 steady-state)
    **Basis**: DI-002 -- power supplies is a shared CAS22 account
    */
    :>> scope = 'CAS Scope'::shared;

    attribute purchase_cost_per_module : Real;
    // ---- inputs the plant wires (WI-057): values produced elsewhere, read here by name ----
    attribute p_et : Real;   // <- pb.p_et
    :>> capital_cost = power_supplies_cost.cost;
    // ---- template calcs (WI-057): the analyses this part owns ----
    // Power supplies (CAS22.1.7).
    calc power_supplies_cost : 'Supplied Purchase Cost' {
        in purchase_cost_in = purchase_cost_per_module;
        in n_mod_in = 1.0;
    }
}

attribute b_fit : Real;
attribute T_offset_fit : Real;
attribute T2_min : Real;
attribute T2_max : Real;
attribute delta_eta : Real default 0.0;
doc /*
WI-080/MR-7 scope: the independently supplied package specification is evaluated against actual gross power, steam flow, shaft work, pump demand, condenser duty and required UA. Point-condition mismatch is unsupported. WI-079 prices its independently supplied package amount. These scalar screens do not qualify the installed machine or exchanger geometry.

CAS23 Turbine plant equipment (steam TG, condenser, feedwater) uses the supplied package purchase amount. The entering estimate used thermal-electric power to price this package; operation no longer changes its purchase amount.

**Source**: /home/reid/1cfe/1costingfe/src/costingfe/layers/costs.py
**Ref**: costs.py:154 (cas23_turbine)
**Basis**: Historical estimate provenance; current supplied package amount is an assumed offer, not a vendor quotation.
*/
:>> scope = 'CAS Scope'::shared;

attribute purchase_cost_per_module : Real;

    connect condenser.rejection to cycle_rejection;
    connect conversion_losses to cycle_rejection;
    connect pump_electric_in to condensate_pump.electric_in;
    connect pump_electric_in to feedwater_pump.electric_in;
    connect salt_distributor.main_branch to main_steam_generator.salt;
    connect salt_distributor.reheat_branch to reheater.salt;
    calc turbine_cost : 'Supplied Purchase Cost' {
        in purchase_cost_in = purchase_cost_per_module;
        in n_mod_in = n_mod;
    }
}

part def 'Electric Plant' :> 'CAS24 Electric Plant' {
    attribute installed_gross_rating_MWe : Real default 0.0; // supplied [MWe]
    calc electric_gross_capability : 'Offered Capacity Screen' {
        in rating_in = installed_gross_rating_MWe;
        in demand_in = p_et;
        in applicable_in = true;
        in conditions_supported_in = true;
        in demand_available_in = true;
    }
    attribute electric_gross_margin : Real = electric_gross_capability.margin;
    attribute electric_gross_applicable : Boolean = electric_gross_capability.applicable;
    attribute electric_gross_supported : Boolean = electric_gross_capability.supported;
    attribute electric_gross_defined : Real = electric_gross_capability.evaluation_defined;
    attribute electric_gross_capacity_ok : Boolean = electric_gross_capability.capacity_ok;

    doc /*
    WI-080/MR-7 scope: installed_gross_rating_MWe is the supplied real-power ceiling and WI-079 purchase basis. Compare actual gross power without resizing. Voltage, reactive power, fault duty and individual electrical equipment remain unqualified.

    CAS24 Electric plant equipment (switchyard, transformers, cabling).
    Linear in gross electric; feeds 'Linear Power Cost' with power = p_et.

    **Source**: /home/reid/1cfe/1costingfe/src/costingfe/layers/costs.py
    **Ref**: costs.py:162 (cas24_electrical)
    **Basis**: Concept-agnostic electric plant, scales with gross electric
    */
    // ---- ports (WI-057): the exchanges this part takes part in; declarative, see mfe_interfaces ----
    port gross_in : ~'Electric Port';   // <- turbine.gross_electric
    port grid : 'Electric Port';   // the net electric output; unconnected -- the model has no grid part (design D7)
    port recirculating : 'Electric Port';   // -> heating, heat_transport, cryoplant, power_supplies, fuel_cycle (pb's recirculating terms)
    :>> scope = 'CAS Scope'::shared;

    attribute cost_per_mw : Real;
    // ---- inputs the plant wires (WI-057): values produced elsewhere, read here by name ----
    attribute n_mod : Real;   // <- 'MFE Power Plant'::n_mod
    attribute p_et : Real;   // <- pb.p_et
    :>> capital_cost = electric_cost.cost;
    // ---- template calcs (WI-057): the analyses this part owns ----
    calc electric_cost : 'Linear Power Cost' {
        in power = installed_gross_rating_MWe;
        in cost_per_mw = 'Electric Plant'::cost_per_mw;
        in n_mod_in = n_mod;
    }
}

part def 'Heat Rejection' :> 'CAS25 Heat Rejection' {
    attribute rated_water_inlet_C : Real default 0.0; // supplied [degC]

        in q_rejection_before_cooling_MW_in = cycle_rejection_MW;
        in condenser_temperature_C_in = cycle_condenser_C;
        in water_inlet_C_in = water_inlet_C;
        in water_outlet_C_in = water_outlet_C;
        in head_m_in = circulating_water_pump.head_m;
        in eta_pump_in = circulating_water_pump.efficiency;
        in eta_motor_in = circulating_water_pump.motor_efficiency;
    }
    calc heat_rejection_cost : 'Supplied Purchase Cost' {
        in purchase_cost_in = purchase_cost_per_module;
        in n_mod_in = n_mod;
    }
}

part def 'Miscellaneous Plant' :> 'CAS26 Miscellaneous' {
    doc /*
    CAS26 Miscellaneous plant equipment (fire protection, compressed air,
    HVAC). Linear in gross electric; feeds 'Linear Power Cost' with
    power = a selected gross-electric procurement class. (1costingFE numbers this account CAS25 -- see header note.) This broad budget assumption does not establish fire-protection, compressed-air or HVAC equipment adequacy.

    **Source**: /home/reid/1cfe/1costingfe/src/costingfe/layers/costs.py
    **Ref**: costs.py:170 (cas25_misc)
    **Basis**: Concept-agnostic miscellaneous plant, scales with gross electric
    */
    :>> scope = 'CAS Scope'::shared;

    attribute cost_per_mw : Real;
    // ---- inputs the plant wires (WI-057): values produced elsewhere, read here by name ----
    attribute n_mod : Real;   // <- 'MFE Power Plant'::n_mod
    attribute p_et : Real;   // <- pb.p_et
    :>> capital_cost = misc_cost.cost;
    // ---- template calcs (WI-057): the analyses this part owns ----
    attribute cost_gross_class_MWe : Real;
    calc cost_gross_class_MWe_guard : 'Supplied Cost Class' {
        in class_in = cost_gross_class_MWe;
    }
    attribute cost_gross_class_MWe_checked : Real = cost_gross_class_MWe_guard.value;
    calc misc_cost : 'Linear Power Cost' {
        in power = cost_gross_class_MWe_checked;
        in cost_per_mw = 'Miscellaneous Plant'::cost_per_mw;
        in n_mod_in = n_mod;
    }
}

// --- Buildings (CAS21, physical facilities with a preserved legacy selector) ---

// ---- CAS22 tail accounts (WI-028 D1/D5; bases bound at instance) ----
// C220110 remote handling (per-module p_et; concept-scaled).
// rh_base[fuel] [$]
attribute remote_handling_base : Real;
// 1.0 toroidal / 0.55 end-access
attribute concept_scale : Real;
attribute remote_handling_cost_gross_class_MWe : Real;
calc remote_handling_cost_gross_class_MWe_guard : 'Supplied Cost Class' {
    in class_in = remote_handling_cost_gross_class_MWe;
}
attribute remote_handling_cost_gross_class_MWe_checked : Real = remote_handling_cost_gross_class_MWe_guard.value;
calc remote_handling : 'Remote Handling Cost' {
    in base = remote_handling_base;
    in concept_scale_in = concept_scale;
    in p_et_in = remote_handling_cost_gross_class_MWe_checked;
}
// expose for producer aggregation
attribute remote_handling_capital : Real = remote_handling.cost;
// C220111 installation labor = frac * Sigma(C220101..C220110).
// reactor_subtotal via an intermediate attribute (WI-025 rollup pattern:
// calc inputs bind to a single attribute, not a mixed expression).
// 0.14 (cas22.py:664)
attribute installation_frac : Real;
attribute reactor_equipment_subtotal : Real =
    powercore_capital + remote_handling_capital;
calc installation : 'Installation Labor Cost' {
    in installation_frac_in = installation_frac;
    in reactor_subtotal = reactor_equipment_subtotal;
}
// C220300 aux cooling (plant-total p_th) + cryoplant (per-module p_cryo).
// 1.10e-3 M$/MW -> $/MW
attribute aux_per_mw : Real;
// C220400 waste (a=1.0), C220500 fuel, C220600 other, C220700 I&C:
// shared 'Plant Power-Law Cost'. Account-structural ref/alpha literal;
// base bound at instance.
// 1.96 M$ -> $
attribute waste_base : Real;
attribute waste_cost_thermal_class_MW : Real;
calc waste_cost_thermal_class_MW_guard : 'Supplied Cost Class' {
    in class_in = waste_cost_thermal_class_MW;
}
attribute waste_cost_thermal_class_MW_checked : Real = waste_cost_thermal_class_MW_guard.value;
calc waste : 'Plant Power-Law Cost' {
    in base = waste_base; in power = waste_cost_thermal_class_MW_checked; in n_mod_in = n_mod;
    in ref_power = 1000.0; in alpha = 1.0;
}
// 11.5 M$ -> $
attribute other_rpe_base : Real;
attribute other_rpe_cost_net_class_MWe : Real;
calc other_rpe_cost_net_class_MWe_guard : 'Supplied Cost Class' {
    in class_in = other_rpe_cost_net_class_MWe;
}
attribute other_rpe_cost_net_class_MWe_checked : Real = other_rpe_cost_net_class_MWe_guard.value;
calc other_rpe : 'Plant Power-Law Cost' {
    in base = other_rpe_base; in power = other_rpe_cost_net_class_MWe_checked; in n_mod_in = n_mod;
    in ref_power = 1000.0; in alpha = 0.8;
}
// WI-070: C220700 owns distinct plasma/central supervisory controls; C220500 owns its package-local controls.
// The unchanged 85 M$ coefficient is an uncalibrated residual allowance, not a historically disaggregated price.
attribute inc_base : Real;
attribute inc_cost_thermal_class_MW : Real;
calc inc_cost_thermal_class_MW_guard : 'Supplied Cost Class' {
    in class_in = inc_cost_thermal_class_MW;
}
attribute inc_cost_thermal_class_MW_checked : Real = inc_cost_thermal_class_MW_guard.value;
calc inc_cost : 'Plant Power-Law Cost' {
    in base = inc_base; in power = inc_cost_thermal_class_MW_checked; in n_mod_in = n_mod;
    in ref_power = 3500.0; in alpha = 0.65;
}

// Expose each tail calc cost as a sibling attribute so cas22_tail_capital
// is a sum-of-siblings aggregation producer (not expose_computed).
// remote_handling_capital is exposed above (installation subtotal).
attribute installation_capital : Real = installation.cost;
attribute coolant_capital : Real = heat_transport.coolant_cost;

// c23..c28 subtotal -- CAS50 spares base (WI-028 F-1).
attribute cas23_to_28_capital : Real =
    bop_capital + special_materials_capital + cas28_capital;

// ---- CAS40 owner + CAS50 supplementary at overnight (no CAS29/CAS30) ----
// owner_cost[fuel] [$]
attribute owner_base : Real;
attribute owner_cost_net_class_MWe : Real;
calc owner_cost_net_class_MWe_guard : 'Supplied Cost Class' {
    in class_in = owner_cost_net_class_MWe;
}
attribute owner_cost_net_class_MWe_checked : Real = owner_cost_net_class_MWe_guard.value;
calc owner : 'Plant Power-Law Cost' {
    in base = owner_base; in power = owner_cost_net_class_MWe_checked; in n_mod_in = n_mod;
    in ref_power = 1000.0; in alpha = 0.5;
}
// CAS40 (expose calc cost as sibling attr)
attribute owner_capital : Real = owner.cost;
// fuel-keyed
attribute supplementary_spares_frac : Real;
// fuel-keyed [$]
attribute supplementary_startup_base : Real;
// fuel-keyed [$]
attribute supplementary_decom_base : Real;

